3: import { defaultTransformer } from '../../transformer';
4: import type { AnyRouter, AnyRouterDef, Router, RouterDef } from '../router';
5: import { createRouterFactory } from '../router';
6: import { mergeWithoutOverrides } from './mergeWithoutOverrides';
