8: /**
9:  * @internal
10:  */
11: export type MergeRouters<
12:   TRouters extends AnyRouter[],
13:   TRouterDef extends AnyRouterDef = RouterDef<
14:     TRouters[0]['_def']['_config'],
15:     // eslint-disable-next-line @typescript-eslint/ban-types
16:     {}
17:   >,
18: > = TRouters extends [
19:   infer Head extends AnyRouter,
20:   ...infer Tail extends AnyRouter[],
21: ]
22:   ? MergeRouters<
23:       Tail,
24:       {
25:         _config: TRouterDef['_config'];
26:         router: true;
27:         procedures: Head['_def']['procedures'] & TRouterDef['procedures'];
28:         record: Head['_def']['record'] & TRouterDef['record'];
29:         queries: Head['_def']['queries'] & TRouterDef['queries'];
30:         mutations: Head['_def']['mutations'] & TRouterDef['mutations'];
31:         subscriptions: Head['_def']['subscriptions'] &
32:           TRouterDef['subscriptions'];
33:       }
34:     >
35:   : Router<TRouterDef> & TRouterDef['record'];
36: 
37: export function mergeRouters<TRouters extends AnyRouter[]>(
38:   ...routerList: [...TRouters]
39: ): MergeRouters<TRouters> {
40:   const record = mergeWithoutOverrides(
41:     {},
42:     ...routerList.map((r) => r._def.record),
43:   );
44:   const errorFormatter = routerList.reduce(
45:     (currentErrorFormatter, nextRouter) => {
46:       if (
47:         nextRouter._def._config.errorFormatter &&
48:         nextRouter._def._config.errorFormatter !== defaultFormatter
49:       ) {
50:         if (
51:           currentErrorFormatter !== defaultFormatter &&
52:           currentErrorFormatter !== nextRouter._def._config.errorFormatter
53:         ) {
54:           throw new Error('You seem to have several error formatters');
55:         }
56:         return nextRouter._def._config.errorFormatter;
57:       }
58:       return currentErrorFormatter;
59:     },
60:     defaultFormatter,
61:   );
62: 
63:   const transformer = routerList.reduce((prev, current) => {
64:     if (
65:       current._def._config.transformer &&
66:       current._def._config.transformer !== defaultTransformer
67:     ) {
68:       if (
69:         prev !== defaultTransformer &&
70:         prev !== current._def._config.transformer
71:       ) {
72:         throw new Error('You seem to have several transformers');
73:       }
74:       return current._def._config.transformer;
75:     }
76:     return prev;
77:   }, defaultTransformer as CombinedDataTransformer);
78: 
79:   const router = createRouterFactory({
80:     errorFormatter,
81:     transformer,
82:     isDev: routerList.some((r) => r._def._config.isDev),
83:     allowOutsideOfServer: routerList.some(
84:       (r) => r._def._config.allowOutsideOfServer,
85:     ),
86:     isServer: routerList.some((r) => r._def._config.isServer),
87:     $types: routerList[0]?._def._config.$types as any,
88:   })(record);
89:   return router as any;
90: }
